def freeze_current_weights(apps, schema_editor):
    """Congela, en cada calificación completa ya calculada, la ponderación vigente hoy (por posición o,
    si no tiene propia, la de su nivel): así editar el catálogo después no reescribe la historia."""
    FinalScore = apps.get_model("evaluations", "FinalScore")
    PositionPillarWeight = apps.get_model("catalog", "PositionPillarWeight")
    PillarWeight = apps.get_model("catalog", "PillarWeight")
    own = {(w.position.area_id, w.position.level_id): w
           for w in PositionPillarWeight.objects.select_related("position").filter(position__is_active=True)}
    by_level = {w.level_id: w for w in PillarWeight.objects.all()}
    for fs in FinalScore.objects.filter(is_complete=True).select_related("user"):
        row = own.get((fs.user.area_id, fs.user.level_id)) or by_level.get(fs.user.level_id)
        if row is None:
            continue
        FinalScore.objects.filter(pk=fs.pk).update(
            w_ownership=row.w_ownership, w_value_delivery=row.w_value_delivery, w_arena_impact=row.w_arena_impact)


